effect.shader:
/**
 * A distância ao plano da faixa nítida, projetada no eixo perpendicular à faixa.
 * `angleDeg` gira a faixa — 0° deixa horizontal, 90° vertical.
 */
float distanciaAoFoco(vec2 uv) {
    vec2 centro = vec2(0.5, focus);
    vec2 d = uv - centro;
    float a = radians(angleDeg);
    // Eixo perpendicular à faixa: a faixa segue cos/sin, a normal segue −sin/cos.
    vec2 normal = vec2(-sin(a), cos(a));
    return abs(dot(d, normal));
}

/**
 * 9 amostras em cruz (5 horizontais + 5 verticais, o centro conta duas vezes).
 * Dá um box blur aproximado controlado por `raioPx`.
 */
vec4 borrar(vec2 uv, float raioPx) {
    vec2 tam = vec2(textureSize(inputImg, 0));
    vec2 passo = raioPx / tam;

    vec4 soma = vec4(0.0);
    soma += texture(inputImg, uv + vec2(-passo.x, 0.0));
    soma += texture(inputImg, uv + vec2(passo.x, 0.0));
    soma += texture(inputImg, uv + vec2(-passo.x * 0.5, 0.0));
    soma += texture(inputImg, uv + vec2(passo.x * 0.5, 0.0));
    soma += texture(inputImg, uv + vec2(0.0, -passo.y));
    soma += texture(inputImg, uv + vec2(0.0, passo.y));
    soma += texture(inputImg, uv + vec2(0.0, -passo.y * 0.5));
    soma += texture(inputImg, uv + vec2(0.0, passo.y * 0.5));
    soma += texture(inputImg, uv) * 2.0;

    return soma / 10.0;
}

void main() {
    float distancia = distanciaAoFoco(acScreenNorm);

    // Fora da banda nítida, o raio cresce com a distância, limitado em `maxBlur`.
    float inicioDaFalta = band * 0.5;
    float fimDaTransicao = inicioDaFalta + max(softness, 1e-4);
    float t = smoothstep(inicioDaFalta, fimDaTransicao, distancia);
    float raio = t * maxBlur;

    vec4 cor = raio < 0.01 ? texture(inputImg, acScreenNorm) : borrar(acScreenNorm, raio);

    fragColor = cor;
}
